def translate_char_list(source_char_list, carrier, reverse=False, encoding=False):
    u"""translate list of unicode emoji character to unicode carrier emoji character (or reverse)

    Attributes:
        source_char_list   - list of emoji characters. it must be unicode instance or have to set `encoding` attribute to decode
        carrier            - the target carrier
        reverse            - if you want to translate CARRIER => UNICODE, turn it True
        encoding           - encoding name for decode (Default is None)

    Returns:
        list of unicode emoji characters
    """

    if isinstance(source_char_list, unicode):
        source_char_list = source_char_list.decode(encoding)

    if reverse:
        return [source_char.translate(carrier.decode(encoding)) for source_char in source_char_list]
    else:
        return [source_char.translate(carrier.decode(encoding).maketrans('', '')) for source_char in source_char_list]


